                Assert.Equal(AtmStatus.Ok, ba.Premier.Status);
                Assert.Equal(AtmStatus.Ok, ba.Second.Status);
                Assert.Equal(ab.Stock, ba.Stock);
                Assert.Equal(ab.Second.Account, ba.Second.Account);
