using System.Reflection;
using FsCheck;
using FsCheck.Fluent;
namespace Atm.Tests;
public class SondeTemp
{
    static Gen<T> G<T>(string nom) => (Gen<T>)typeof(Proprietes).GetField(nom, BindingFlags.NonPublic | BindingFlags.Static)!.GetValue(null)!;
    static AtmResult Run(Proprietes.Situation s, Operation op) => new CashMachine(new MoneyDispenser(s.Stock, s.Bloquee)).Execute(s.Compte, op);
    [Fact]
    public void Sonde()
    {
